"""Text statistics."""


def count_words(text):
    """Case-insensitive count of each word in `text`."""
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

original_test_src:
from wordcount import count_words

def test_punctuation_dropped():
    assert count_words('Hi, hi! hi.') == {'hi': 3}
    assert count_words('a-b a b') == {'a': 2, 'b': 2}
    assert count_words('(x) [x]') == {'x': 2}
def test_apostrophe_splits():
    assert count_words("it's ok") == {'it': 1, 's': 1, 'ok': 1}
def test_case_and_digits():
    assert count_words('The cat THE') == {'the': 2, 'cat': 1}
    assert count_words('r2 r2 d2') == {'r2': 2, 'd2': 1}
def test_empty():
    assert count_words('') == {}
    assert count_words('   ') == {}
    assert count_words('!!! ...') == {}

